 "s01/dinh-dang": "$ ls formats/\ncef.log\nevent-4625.xml\njson.log\nlogfmt.log\nrfc3164.log\nrfc5424.log\n$ cat formats/rfc3164.log formats/rfc5424.log\n<38>Nov 20 02:10:03 web-01 sshd[41001]: Failed password for an from 203.0.113.66 port 51515 ssh2\n<38>1 2026-11-20T02:10:03.512+07:00 web-01 sshd 41001 - [origin ip=\"10.0.0.10\"] Failed password for an from 203.0.113.66 port 51515 ssh2\n$ cut -d' ' -f1-4 formats/rfc5424.log\n<38>1 2026-11-20T02:10:03.512+07:00 web-01 sshd\n$ jq -r '[.user, .src_ip, .event] | @tsv' formats/json.log\nan\t203.0.113.66\tlogin_failed\n$ grep -oE '(user|src_ip|event)=[^ ]+' formats/logfmt.log\nevent=login_failed\nuser=an\nsrc_ip=203.0.113.66\n$ awk -F'|' '{print \"vendor=\" $2, \"product=\" $3, \"signature=\" $5, \"severity=\" $7}' formats/cef.log\nvendor=OpenBSD product=OpenSSH signature=login_failed severity=5\n$ grep -oE '<EventID>[0-9]+|Name=\"(TargetUserName|IpAddress|LogonType)\">[^<]+' formats/event-4625.xml\n<EventID>4625\nName=\"TargetUserName\">an\nName=\"LogonType\">3\nName=\"IpAddress\">203.0.113.66\n$ grep -c 'Failed password' formats/*\nformats/cef.log:1\nformats/event-4625.xml:0\nformats/json.log:1\nformats/logfmt.log:1\nformats/rfc3164.log:1\nformats/rfc5424.log:1",
